// The scoping, without Playwright.
let capturedId = "";                    // declared out here

function pretendHook(): void {
  const fromServer = "id-42";           // block-scoped: dies with the function
  capturedId = fromServer;              // assigned to the outer variable
}

console.log("before hook:", JSON.stringify(capturedId));
pretendHook();
console.log("after hook :", JSON.stringify(capturedId), "<- the tests can see this");

const BASE = "https://demoqa.com";
const userId = "9b09305e-e878";

console.log("concatenated:", BASE + "/Account/v1/User/" + userId);
console.log("template    :", `${BASE}/Account/v1/User/${userId}`);

// The trap concatenation invites: a missing slash, silently.
console.log("missing / ->", BASE + "Account/v1/User/" + userId, "<- broken URL, no error");

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week7/generated/day4-chaining.spec.ts", `// Week 7, Day 4 — one response feeds the next request.
//
// The problem this file solves: to update or delete something, you need its id.
// The server invents the id. So you cannot hard-code it — you have to create the
// thing first, catch the id, and carry it forward.
//
// Written by a cell in week7/day4_2.ipynb. Run it yourself:
//   npx playwright test week7/generated/day4-chaining.spec.ts
import { test, expect } from "@playwright/test";

const BASE_URL = "https://demoqa.com";
const GIT_BOOK = "9781449325862";
const JS_BOOK = "9781449331818";

test.describe("Create, then use what you got back", () => {
  // These tests are one journey, in order, sharing a user.
  test.describe.configure({ mode: "serial" });

  const userName = \`w7d4_\${Date.now()}\`;
  const password = "Passw0rd@123";

  // Declared out here so every test can see them; assigned in beforeAll.
  let userId = "";
  let token = "";

  // beforeAll, NOT beforeEach: creating the user is a prerequisite for the whole
  // block, and doing it per test would make four users and leave three behind.
  test.beforeAll(async ({ request }) => {
    const created = await request.post(\`\${BASE_URL}/Account/v1/User\`, {
      data: { userName, password },
    });
    expect(created.status()).toBe(201);
    userId = (await created.json()).userID;

    const tokenResponse = await request.post(\`\${BASE_URL}/Account/v1/GenerateToken\`, {
      data: { userName, password },
    });
    token = (await tokenResponse.json()).token;
    expect(token).toBeTruthy();
  });

  test("Step 1 — the prerequisite actually produced something", async () => {
    expect(userId).toBeTruthy();
    expect(token).toBeTruthy();
  });

  test("Step 2 — without the token, the door is shut", async ({ request }) => {
    const response = await request.get(\`\${BASE_URL}/Account/v1/User/\${userId}\`);

    // 401: authenticated as nobody. The id alone is not permission.
    expect(response.status()).toBe(401);
    expect((await response.json()).message).toContain("not authorized");
  });

  test("Step 3 — the same request, with the header", async ({ request }) => {
    const response = await request.get(\`\${BASE_URL}/Account/v1/User/\${userId}\`, {
      // headers is the third thing a request can carry, alongside the URL and
      // the body. "Bearer <token>" is the convention for a token in one.
      headers: { Authorization: \`Bearer \${token}\` },
    });

    expect(response.status()).toBe(200);
    const body = await response.json();
    expect(body.username).toBe(userName);
    expect(body.books).toEqual([]);      // a brand-new user owns nothing
  });

  test("Step 4 — POST using the captured id", async ({ request }) => {
    const response = await request.post(\`\${BASE_URL}/BookStore/v1/Books\`, {
      headers: { Authorization: \`Bearer \${token}\` },
      // The id goes in the BODY here. Some APIs want it in the URL, some in the
      // body; only the documentation tells you which.
      data: { userId, collectionOfIsbns: [{ isbn: GIT_BOOK }, { isbn: JS_BOOK }] },
    });

    expect(response.status()).toBe(201);
    expect((await response.json()).books).toHaveLength(2);
  });

  test("Step 5 — PUT replaces one book with another", async ({ request }) => {
    const response = await request.put(\`\${BASE_URL}/BookStore/v1/Books/\${GIT_BOOK}\`, {
      headers: { Authorization: \`Bearer \${token}\` },
      data: { userId, isbn: "9781491904244" },
    });

    expect(response.status()).toBe(200);

    // Assert on the CONSEQUENCE, not just the status: read the collection back.
    const after = await request.get(\`\${BASE_URL}/Account/v1/User/\${userId}\`, {
      headers: { Authorization: \`Bearer \${token}\` },
    });
    const isbns = (await after.json()).books.map((b: { isbn: string }) => b.isbn);
    expect(isbns).toContain("9781491904244");
    expect(isbns).not.toContain(GIT_BOOK);
  });

  test("Step 6 — DELETE answers 204, and has no body at all", async ({ request }) => {
    const response = await request.delete(\`\${BASE_URL}/BookStore/v1/Book\`, {
      headers: { Authorization: \`Bearer \${token}\` },
      data: { isbn: JS_BOOK, userId },
    });

    // 204 = "done, and there is nothing to tell you".
    expect(response.status()).toBe(204);

    const raw = await response.text();
    expect(raw).toBe("");

    // So parsing it throws. The session hits exactly this and has to delete the
    // line. An empty string is not valid JSON — there is no object to make.
    await expect(response.json()).rejects.toThrow();
  });

  test.afterAll(async ({ request }) => {
    if (!userId || !token) return;
    const gone = await request.delete(\`\${BASE_URL}/Account/v1/User/\${userId}\`, {
      headers: { Authorization: \`Bearer \${token}\` },
    });
    expect(gone.status()).toBe(204);
  });
});
`);

// Expected: 6 passed. Watch the order: nothing works until beforeAll has run.
await runSpec("week7/generated/day4-chaining.spec.ts");

// The same endpoint, three ways, so the 401 is unmistakable.
const B = "https://demoqa.com";
const J = { "Content-Type": "application/json" };
const who = { userName: `w7d4x_${Date.now()}`, password: "Passw0rd@123" };

const made = await (await fetch(`${B}/Account/v1/User`, { method: "POST", headers: J, body: JSON.stringify(who) })).json();
const bearer = (await (await fetch(`${B}/Account/v1/GenerateToken`, { method: "POST", headers: J, body: JSON.stringify(who) })).json()).token;

for (const [label, headers] of [
  ["no header at all", {}],
  ["a wrong token", { Authorization: "Bearer not-a-real-token" }],
  ["the real token", { Authorization: `Bearer ${bearer}` }],
] as [string, Record<string, string>][]) {
  const r = await fetch(`${B}/Account/v1/User/${made.userID}`, { headers });
  console.log(`${label.padEnd(18)} -> ${r.status}`);
}

await fetch(`${B}/Account/v1/User/${made.userID}`, { method: "DELETE", headers: { Authorization: `Bearer ${bearer}` } });
console.log("cleaned up");

// Reproduce it deliberately: parse an empty body.
try {
  JSON.parse("");
} catch (e) {
  console.log("JSON.parse('') ->", (e as Error).message);
}

console.log();
console.log("So for a 204: assert the status, and read text() if you must - never json().");

// Count the cost of each home, for a suite of 5 files x 6 tests.
const files = 5, testsPerFile = 6, setupLines = 8;

const homes = [
  { name: "in each test", copies: files * testsPerFile, users: files * testsPerFile },
  { name: "beforeEach", copies: files, users: files * testsPerFile },
  { name: "beforeAll", copies: files, users: files },
  { name: "a fixture", copies: 1, users: files },
];

for (const h of homes) {
  console.log(
    `${h.name.padEnd(14)} setup lines: ${String(h.copies * setupLines).padStart(4)}   users created: ${h.users}`,
  );
}

## Worker scope, and why it is tempting

A token is expensive and reusable, so "fetch it once per worker" looks obvious:

```ts
export const test = base.extend<{}, { token: string }>({
  token: [async ({}, use) => {
    await use(await fetchToken());
  }, { scope: "worker" }],
});
```

| Scope | Runs | Good for |
|---|---|---|
| `test` | once per test | anything a test mutates |
| `worker` | once per worker process | a read-only token |

The catch, from [week5/day4_3](/learn/w5/d4/p3): worker-scoped values are **shared**. A
token is fine because nothing changes it. A *user* is not - two tests adding books to the same
account interfere, and the failure depends on the worker count.
